project_name: "p"
constant: RAW_DATASET {
  value: "bq_project.raw"
}

view: orders {
  derived_table: {
    sql: SELECT id FROM `@{RAW_DATASET}.orders` ;;
  }
  dimension: id { sql: ${TABLE}.id ;; }
}

view: order_facts {
  derived_table: {
    sql: SELECT customer_id, COUNT(*) AS order_count
      FROM ${orders.SQL_TABLE_NAME}
      GROUP BY 1 ;;
  }
  dimension: customer_id { sql: ${TABLE}.customer_id ;; }
}

