view: orders_rollup {
  derived_table: {
    sql: SELECT customer_id, COUNT(*) AS order_count
      FROM ${orders.SQL_TABLE_NAME}
      GROUP BY 1 ;;
  }
  dimension: customer_id { sql: ${TABLE}.customer_id ;; }
}

view: orders_rollup_repeat {
  derived_table: {
    sql: SELECT customer_id, order_count
      FROM ${orders_rollup.SQL_TABLE_NAME}
      WHERE order_count > 1 ;;
  }
  dimension: customer_id { sql: ${TABLE}.customer_id ;; }
}

view: orders {
  sql_table_name: raw.orders ;;
  dimension: id { sql: ${TABLE}.id ;; }
}

view: orders_by_customer {
  derived_table: {
    sql: SELECT c.id AS customer_id, COUNT(o.id) AS order_count
      FROM raw.customers AS c
      LEFT JOIN ${orders.SQL_TABLE_NAME} AS o ON o.customer_id = c.id
      GROUP BY 1 ;;
  }
  dimension: customer_id { sql: ${TABLE}.customer_id ;; }
}

