connection: "wh"
include: "/views/*.view.lkml"
explore: orders {
  join: users {
    sql_on: ${orders.user_id} = ${users.id} ;;
    relationship: many_to_one
  }
}

view: orders {
  sql_table_name: raw.orders ;;
  dimension: id { sql: ${TABLE}.id ;; }
  dimension: user_id { sql: ${TABLE}.user_id ;; }
  measure: count { type: count }
}

view: orders_by_country {
  derived_table: {
    explore_source: orders {
      column: country { field: users.country }
      column: order_count { field: orders.count }
    }
  }
  dimension: country {}
  dimension: order_count { type: number }
}

view: users {
  sql_table_name: raw.users ;;
  dimension: id { sql: ${TABLE}.id ;; }
  dimension: country { sql: ${TABLE}.country ;; }
}

